SELECT article_id, author_id, title, summary, cover, status, visibility,
       publish_time, revise_time, create_time, update_time
FROM articles
WHERE 
AND author_id = #{authorId}

    AND article_id IN (SELECT article_id FROM article_tags WHERE tag_id = #{tagId})


    AND article_id IN

        #{articleId}



    AND (publish_time < #{cursorPublishTime}
         OR (publish_time = #{cursorPublishTime} AND article_id < #{cursorArticleId}))

ORDER BY publish_time DESC, article_id DESC
LIMIT #{limit}

SELECT article_id, author_id, title, summary, cover, status, visibility, publish_time, revise_time, create_time, update_time FROM articles WHERE AND (title ILIKE #{keywordPattern} ESCAPE '!' OR summary ILIKE #{keywordPattern} ESCAPE '!')
AND (publish_time < #{cursorPublishTime} OR (publish_time = #{cursorPublishTime} AND article_id < #{cursorArticleId}))
ORDER BY publish_time DESC, article_id DESC LIMIT #{limit}
